static int
putnstr(char *out, int o, int n, const char *s)
{
  while (*s != '\0' && o < n)
    out[o++] = *s++;
  return o;
}

static int
putpadding(char *out, int o, int n, int m, char padding)
{
  if (m > n - o)
    m = n - o;
  for (; m > 0; --m)
    out[o++] = padding;
  return o;
}

// Output is not '\0' terminated.
static int
snprintuint(char *out, unsigned int n, unsigned int x,
            int base, const char* digits, int order, int padding)
{
  char buf[16];
  unsigned int i, o;

  i = 0;
  do{
    buf[i++] = digits[x % base];
    x /= base;
  }while(x != 0);

  if (i < order) {
    memset(buf + i, padding, order - i);
    i = order;
  }

  for (o = 0; i > 0 && o < n; ++o)
    out[o] = buf[--i];

  return o;
}

static int
snprintulong(char *out, unsigned int n, unsigned long x,
             int base, const char* digits, int order, int padding)
{
  char buf[32];
  unsigned int i, o;

  i = 0;
  do{
    buf[i++] = digits[x % base];
    x /= base;
  }while(x != 0);

  if (i < order) {
    memset(buf + i, padding, order - i);
    i = order;
  }

  for (o = 0; i > 0 && o < n; ++o)
    out[o] = buf[--i];

  return o;
}

static int
snprintstr(char *out, unsigned int n, const char* s,
           int order, int suborder, int leftalign)
{
  int o = 0;
  if(s == NULL)
    s = "(null)";
  size_t len = strlen(s);
  if (suborder > 0)
    len = MIN(len, suborder);
  if (order <= 0 || len >= order) {
    o = putnstr(out, o, MIN(n, o + len), s);
  } else {
    if (leftalign) {
      o = putnstr(out, o, MIN(n, o + len), s);
      o = putpadding(out, o, n, order - len, ' ');
    } else {
      o = putpadding(out, o, n, order - len, ' ');
      o = putnstr(out, o, MIN(n, o + len), s);
    }
  }
  return o;
}

static int
sprintsign(char *out, int negative, int force, int *porder)
{
  int o = 0;
  if (negative) {
    out[o++] = '-';
  } else if (force) {
    out[o++] = '+';
  }
  if (*porder > 1 && o > 0)
    *porder -= o;
  return o;
}

// Only understands %d, %x, %X, %p, %s, %c, %f and "+-0~9".
// '\0' is not put at the end if the buffer is smaller than output.
int
__xcc_vsnprintf(char *out, size_t n, const char *fmt_, va_list ap)
{
  const unsigned char *fmt = (const unsigned char*)fmt_;
  int c, i;
  int o;

  for(i = o = 0; fmt[i] != '\0' && o < n; i++){
    c = fmt[i];
    if(c != '%'){
      out[o++] = c;
      continue;
    }

    // Handle '%'
    char padding = ' ';
    int order = 0, suborder = 0;
    int sign = 0;
    int leftalign = 0;
    int bLong = 0;
    c = fmt[++i];
    if (c == '+') {
      sign = 1;
      c = fmt[++i];
    } else if (c == '-') {
      leftalign = 1;
      c = fmt[++i];
    }
    if (c == '0') {
      padding = '0';
      c = fmt[++i];
    }
    if (c >= '1' && c <= '9') {
      order = c - '0';
      while (c = fmt[++i], c >= '0' && c <= '9')
        order = order * 10 + (c - '0');
    } else if (c == '*') {
      order = va_arg(ap, int);
    }
    if (c == '.') {
      c = fmt[++i];
      if (isdigit(c)) {
        do {
          suborder = suborder * 10 + (c - '0');
        } while (isdigit(c = fmt[++i]));
      } else if (c == '*') {
        suborder = va_arg(ap, int);
        c = fmt[++i];
      }
    }

    if(c == 'l'){
      bLong = 1;
      c = fmt[++i];
    }
    if(c == 'd'){
      if (bLong) {
        long x = va_arg(ap, long);
        o += sprintsign(out + o, x < 0, sign, &order);
        unsigned long ux = x < 0 ? -x : x;
        o += snprintulong(out + o, n - o, ux, 10, kHexDigits, order, padding);
      } else {
        int x = va_arg(ap, int);
        o += sprintsign(out + o, x < 0, sign, &order);
        unsigned int ux = x < 0 ? -x : x;
        o += snprintuint(out + o, n - o, ux, 10, kHexDigits, order, padding);
      }
    } else if(tolower(c) == 'x') {
      const char *digits = c == 'x' ? kHexDigits : kUpperHexDigits;
      if (bLong) {
        long x = va_arg(ap, long);
        o += snprintulong(out + o, n - o, x, 16, digits, order, padding);
      } else {
        int x = va_arg(ap, int);
        o += snprintuint(out + o, n - o, x, 16, digits, order, padding);
      }
    } else if(c == 'p') {
      void *ptr = va_arg(ap, void*);
      order -= 2;
      if (order < 0)
        order = 0;
      if (order == 0 || padding != ' ') {
        o += snprintstr(out + o, n - o, "0x", 0, 0, 0);
        o += snprintulong(out + o, n - o, (uintptr_t)ptr, 16, kHexDigits, order, padding);
      } else {
        char buf[32];
        int oo = snprintulong(buf, sizeof(buf), (uintptr_t)ptr, 16, kHexDigits, 0, padding);
        if (order > oo)
          o = putpadding(out, o, n, order - oo, padding);
        o += snprintstr(out + o, n - o, "0x", 0, 0, 0);
        o += snprintstr(out + o, n - o, buf, 0, 0, 0);
      }
    } else if(c == 's'){
      // ("%5", "foo")         = "  foo"
      // ("%-5", "foo")        = "foo  "
      // ("%5", "foobarbaz")   = "foobarbaz"
      // ("%.3", "foobarbaz")  = "foo"
      // ("%5.7", "foobarbaz") = "foobarb"
      // ("%5.3", "foobarbaz") = "  foo"

      const char *s = va_arg(ap, const char*);
      o += snprintstr(out + o, n - o, s, order, suborder, leftalign);
    } else if(c == 'c'){
      out[o++] = va_arg(ap, unsigned int);
    } else if(c == '%'){
      out[o++] = c;
#ifndef __NO_FLONUM
    } else if(c == 'f'){
      double x = va_arg(ap, double);

      o += sprintsign(out + o, x < 0, sign, &order);
      x = x < 0 ? -x : x;

      long intPart = x >= 0 ? (long)x : -(long)(-x);
      o += snprintulong(out + o, n - o, intPart, 10, kHexDigits,
                        order, padding);
      if (o < n) {
        out[o++] = '.';
        suborder = suborder > 0 ? suborder : 6;
        unsigned long fraction = (unsigned long)((x - intPart) * pow10(suborder));
        o += snprintulong(out + o, n - o, fraction, 10, kHexDigits,
                          suborder, '0');
      }
#endif
    } else {
      // Unknown % sequence.  Print it to draw attention.
      out[o++] = '%';
      if (o >= n)
        break;
      if (c != '\0')
        out[o++] = c;
    }
  }

  if (o < n)
    out[o] = '\0';
  return o;
}

